726	// Merge a fresh inbox page into the accumulated cache, deduping by thread id
727	// (a thread can straddle a page boundary, so the same id may recur).
728	function mergeInbox(base, page) {
729	  base = base || {};
730	  base.pinned = base.pinned || [];
731	  base.primary = base.primary || [];
732	  base.bundles = base.bundles || [];
733	  base.email = base.email || page.email;
734	  const seen = new Set();
735	  base.pinned.forEach((r) => seen.add(r.id));
736	  base.primary.forEach((r) => seen.add(r.id));
737	  base.bundles.forEach((b) => b.items.forEach((r) => seen.add(r.id)));
738	  const addAll = (arr, items) => (items || []).forEach((r) => {
739	    if (!seen.has(r.id)) { arr.push(r); seen.add(r.id); }
740	  });
741	  addAll(base.pinned, page.pinned);
742	  addAll(base.primary, page.primary);
743	  (page.bundles || []).forEach((pb) => {
744	    let bb = base.bundles.find((x) => x.name === pb.name);
745	    if (!bb) { bb = { name: pb.name, icon: pb.icon, color: pb.color, count: 0, items: [] }; base.bundles.push(bb); }
746	    addAll(bb.items, pb.items);
747	    bb.count = bb.items.length;
748	  });
749	  return base;
750	}
751	
752	// "Load more": fetch only the NEXT page via pageToken and append it.
753	async function loadMore() {
754	  if (!STATE.token) return;
755	  const v = STATE.view;
756	  const lim = "limit=" + PAGE;
757	  const tok = "&pageToken=" + encodeURIComponent(STATE.token);
758	  if (v === "inbox" || v === "pinned" || v.startsWith("bundle:")) {
759	    const p = await api("/api/inbox?" + lim + tok);
760	    STATE.inboxCache = mergeInbox(STATE.inboxCache, p);
761	    STATE.token = p.nextPageToken || null;
762	    if (v === "inbox") { STATE.data = STATE.inboxCache; renderNavBundles(); }
763	    else if (v === "pinned") STATE.data = { items: STATE.inboxCache.pinned || [], email: STATE.inboxCache.email };
764	    else {
765	      const b = (STATE.inboxCache.bundles || []).find((x) => x.name === v.slice(7));
766	      STATE.data = { items: b ? b.items : [], email: STATE.inboxCache.email };
767	    }
768	  } else {
769	    let url;
770	    if (v === "snoozed") url = "/api/snoozed?" + lim + tok;
771	    else if (v === "done") url = "/api/done_list?" + lim + tok;
772	    else if (v === "sent") url = "/api/sent?" + lim + tok;
773	    else if (v === "search") url = "/api/search?q=" + encodeURIComponent(STATE.query || "") + "&" + lim + tok;
774	    else return;
775	    const p = await api(url);
776	    STATE.data.items = STATE.data.items || [];
777	    const seen = new Set(STATE.data.items.map((r) => r.id));
778	    (p.items || []).forEach((r) => { if (!seen.has(r.id)) { STATE.data.items.push(r); seen.add(r.id); } });
779	    STATE.token = p.nextPageToken || null;
780	  }
781	  render();
782	}
783	
784	// ---------- Keep the inbox topped up to ~50 in view ----------
785	const TARGET = PAGE; // keep at least this many conversations visible when more exist
786	function inViewCount() {
787	  const d = STATE.data;
788	  if (!d) return 0;
789	  if (STATE.view === "inbox") {
790	    if ($("#pinnedOnly").checked) return d.pinned?.length || 0;
791	    return (d.pinned?.length || 0) + (d.primary?.length || 0) + (d.bundles || []).reduce((s, b) => s + (b.count || 0), 0);
792	  }
793	  return (d.items || []).length;
794	}
795	async function ensureFilled() {
796	  // Only auto-fill the main inbox view (not pinned-only, which has its own small set)
797	  if (STATE.view !== "inbox" || $("#pinnedOnly").checked || STATE.filling) return;
798	  STATE.filling = true;
799	  try {
800	    let guard = 0;
801	    while (STATE.token && inViewCount() < TARGET && guard < 25) { guard++; await loadMore(); }
802	  } finally {
803	    STATE.filling = false;
804	  }
805	}
806	// Prune a thread from the in-memory model (in place, so shared refs stay consistent)
807	function removeFromData(id) {
808	  const d = STATE.data;
809	  if (!d) return;
810	  const prune = (arr) => { if (arr) { const i = arr.findIndex((r) => r.id === id); if (i >= 0) arr.splice(i, 1); } };
811	  prune(d.pinned); prune(d.primary); prune(d.items);
812	  (d.bundles || []).forEach((b) => { prune(b.items); b.count = b.items.length; });
813	}
814	
815	// nav bundles populated after first load
816	function renderNavBundles() {
817	  const nb = $("#navBundles");
818	  nb.innerHTML = "";
819	  (STATE.data?.bundles || []).forEach((b) => {
820	    const a = document.createElement("a");
821	    a.className = "nav-item";
822	    a.dataset.view = "bundle:" + b.name;
823	    a.innerHTML = `<i class="material-icons" style="color:${b.color}">${b.icon}</i> ${esc(b.name)} <span style="margin-left:auto;color:#9aa0a6;font-weight:400">${b.count}</span>`;
824	    a.onclick = () => {
825	      document.querySelectorAll(".nav-item").forEach((x) => x.classList.remove("active"));
826	      a.classList.add("active");
827	      STATE.view = "bundle:" + b.name;
828	      STATE.token = null;
829	      load();
830	    };
831	    nb.appendChild(a);
832	  });
833	}
834	
835	// ---------- Live sync (Server-Sent Events) ----------
836	let evtSource = null;
837	function startStream() {
838	  if (evtSource) return;
839	  try {
840	    evtSource = new EventSource("/api/stream");
841	    evtSource.onmessage = (e) => {
842	      let msg = {};
843	      try { msg = JSON.parse(e.data); } catch (_) {}
844	      // Deep link asked us to surface a specific thread (from the inboxclone:// handler)
845	      if (msg.focus) { openThread(msg.focus); return; }
846	      // Mailbox changed server-side (new mail / label change). Refresh the current view;
847	      // overlays sit on top and are untouched. Preserve scroll so it doesn't yank.
848	      const scroller = document.scrollingElement || document.documentElement;
849	      const y = scroller.scrollTop;
850	      STATE.inboxCache = null;
851	      load().then(() => { try { scroller.scrollTop = y; } catch (e) {} });
852	    };
853	    // EventSource reconnects automatically on error — nothing to handle.
854	  } catch (e) { /* SSE unsupported */ }
855	}
856	
857	(async function start() {
858	  await load();
859	  renderNavBundles();
860	  startStream();
861	  if (window.OPEN_THREAD) openThread(window.OPEN_THREAD);
862	})();
