  document.documentElement.dataset.theme = dark ? "dark" : "light";
  STATE.imageBlock = s.image_block ?? true;
  STATE.undoSendWindow = s.undo_send_window ?? 10;
  if (s.page_size) PAGE = s.page_size;
}

